function startSpaceInvaders(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    canvas.width = 500;
    canvas.height = 500;
    const W = canvas.width, H = canvas.height;
    const keys = {};
    document.addEventListener('keydown', e => { keys[e.code] = true; });
    document.addEventListener('keyup', e => { keys[e.code] = false; });
    const player = {
        w: 30, h: 20, x: W / 2 - 15, y: H - 40, speed: 5, color: 'cyan', alive: true
    };
    const bullets = [];
    const enemyBullets = [];
    const explosions = [];
    let score = 0, level = 1, gameOver = false, win = false;
    const formation = {
        rows: 5, cols: 11, hSpace: 5, vSpace: 5, offsetX: 50, offsetY: 50,
        enemyW: 30, enemyH: 20, speedX: 0.5, speedY: 10, direction: 1, timer: 0
    };
    let enemies = [];
    function initEnemies() {
        enemies = [];
        for (let r = 0; r < formation.rows; r++) {
            for (let c = 0; c < formation.cols; c++) {
                enemies.push({
                    w: formation.enemyW, h: formation.enemyH,
                    x: formation.offsetX + c * (formation.enemyW + formation.hSpace),
                    y: formation.offsetY + r * (formation.enemyH + formation.vSpace),
                    alive: true, color: 'lime'
                });
            }
        }
    }
    initEnemies();
    function spawnPlayerBullet() {
        bullets.push({x: player.x + player.w/2-2, y: player.y, w:4, h:10, speed:7, color:'white'});
    }
    function spawnEnemyBullet(x, y) {
        enemyBullets.push({x: x+2, y: y+2, w:4, h:10, speed:5, color:'red'});
    }
    function update() {
        if (gameOver) return;
        // player movement
        if (keys['ArrowLeft']) player.x -= player.speed;
        if (keys['ArrowRight']) player.x += player.speed;
        if (player.x < 0) player.x = 0;
        if (player.x + player.w > W) player.x = W - player.w;
        // shooting
        if (keys['Space'] && !keys['SpacePressed']) {
            spawnPlayerBullet();
            keys['SpacePressed'] = true;
        }
        if (!keys['Space']) keys['SpacePressed'] = false;
        // update bullets
        bullets.forEach(b => b.y -= b.speed);
        enemyBullets.forEach(b => b.y += b.speed);
        bullets = bullets.filter(b => b.y + b.h > 0);
        enemyBullets = enemyBullets.filter(b => b.y < H);
        // enemy formation movement
        formation.timer += 1;
        if (formation.timer > 60) {
            formation.timer = 0;
            let edge = false;
            enemies.forEach(e => {
                if (!e.alive) return;
                e.x += formation.speedX * formation.direction;
                if (e.x < 0 || e.x + e.w > W) edge = true;
            });
            if (edge) {
                formation.direction *= -1;
                enemies.forEach(e => { if (e.alive) e.y += formation.speedY; });
            }
        }
        // enemy shooting
        if (Math.random() < 0.02) {
            const shooters = enemies.filter(e => e.alive);
            if (shooters.length) {
                const shooter = shooters[Math.floor(Math.random()*shooters.length)];
                spawnEnemyBullet(shooter.x, shooter.y);
            }
        }
        // collisions player bullets vs enemies
        bullets.forEach(b => {
            enemies.forEach(e => {
                if (e.alive && b.x < e.x+e.w && b.x+b.w > e.x && b.y < e.y+e.h && b.y+b.h > e.y) {
                    e.alive = false;
                    b.alive = false;
                    score += 10;
                    explosions.push({x:e.x+e.w/2, y:e.y+e.h/2, r:0, maxR:15, life:30});
                }
            });
        });
        // collisions enemy bullets vs player
        enemyBullets.forEach(b => {
            if (player.alive && b.x < player.x+player.w && b.x+b.w > player.x && b.y < player.y+player.h && b.y+b.h > player.y) {
                player.alive = false;
                gameOver = true;
                explosions.push({x:player.x+player.w/2, y:player.y+player.h/2, r:0, maxR:20, life:40});
            }
        });
        // remove dead bullets
        bullets = bullets.filter(b => b.alive !== false);
        // explosions update
        explosions.forEach(e => {
            e.r += e.maxR/30;
            e.life--;
        });
        explosions = explosions.filter(e => e.life>0);
        // win/lose checks
        if (!enemies.some(e=>e.alive)) {
            win = true;
            level++;
            formation.speedX += 0.1;
            formation.speedY += 1;
            initEnemies();
        }
        if (enemies.some(e=>e.alive && e.y+e.h >= H-50)) {
            gameOver = true;
        }
    }
    function draw() {
        ctx.clearRect(0,0,W,H);
        // player
        if (player.alive) {
            ctx.fillStyle = player.color;
            ctx.beginPath();
            ctx.moveTo(player.x, player.y+player.h);
            ctx.lineTo(player.x+player.w/2, player.y);
            ctx.lineTo(player.x+player.w, player.y+player.h);
            ctx.closePath();
            ctx.fill();
        }
        // enemies
        enemies.forEach(e => {
            if (e.alive) {
                ctx.fillStyle = e.color;
                ctx.fillRect(e.x, e.y, e.w, e.h);
            }
        });
        // bullets
        bullets.forEach(b => {
            ctx.fillStyle = b.color;
            ctx.fillRect(b.x, b.y, b.w, b.h);
        });
        enemyBullets.forEach(b => {
            ctx.fillStyle = b.color;
            ctx.fillRect(b.x, b.y, b.w, b.h);
        });
        // explosions
        explosions.forEach(e => {
            ctx.strokeStyle = 'orange';
            ctx.beginPath();
            ctx.arc(e.x, e.y, e.r,0,Math.PI*2);
            ctx.stroke();
        });
        // UI
        ctx.fillStyle = 'white';
        ctx.font = '16px sans-serif';
        ctx.fillText('Score: '+score,10,20);
        ctx.fillText('Level: '+level,10,40);
        if (gameOver) {
            ctx.fillStyle = 'red';
            ctx.font = '48px sans-serif';
            ctx.fillText('Game Over',W/2-120,H/2);
        } else if (win) {
            ctx.fillStyle = 'lime';
            ctx.font = '48px sans-serif';
            ctx.fillText('Level Up!',W/2-130,H/2);
        }
    }
    function loop() {
        update();
        draw();
        if (!gameOver) requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
}
